<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($asset['asset_code']) ?> · <?= e($asset['tenant_name']) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6fb}.wrap{max-width:820px;margin:0 auto;padding:28px 16px}.card{border:0;border-radius:18px;box-shadow:0 10px 35px #1e293b12}.badge{font-size:.8rem}.timeline{border-left:2px solid #e2e8f0;padding-left:18px}.timeline div{margin:0 0 18px}</style></head><body><main class="wrap"><div class="card p-4 mb-3"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><small class="text-secondary">Asset Service Passport</small><h1 class="h3 mb-1"><?= e($asset['asset_code']) ?></h1><p class="mb-0"><?= e(trim(($asset['brand']??'').' '.($asset['model']??''))) ?> · <?= e($asset['category']??'Asset') ?></p></div><span class="badge text-bg-success align-self-start"><?= e($asset['status']) ?></span></div><hr><div class="row g-3"><div class="col-md-6"><small class="text-secondary">Customer</small><div><?= e($asset['customer_name']) ?></div></div><div class="col-md-6"><small class="text-secondary">Site</small><div><?= e($asset['site_name']??'-') ?></div><small><?= e($asset['site_address']??'') ?></small></div><div class="col-md-4"><small class="text-secondary">Serial</small><div><?= e($asset['serial_number']??'-') ?></div></div><div class="col-md-4"><small class="text-secondary">Last Service</small><div><?= e($asset['last_service']??'-') ?></div></div><div class="col-md-4"><small class="text-secondary">Next Service</small><div><?= e($asset['next_service']??'-') ?></div></div></div></div><div class="card p-4 mb-3"><h2 class="h5">Service History</h2><div class="timeline"><?php if(!$jobs): ?><p class="text-secondary">No service history yet.</p><?php endif; ?><?php foreach($jobs as $j): ?><div><strong><?= e($j['job_number']) ?> · <?= e($j['service_category']??'Service') ?></strong><br><span class="badge text-bg-light"><?= e($j['status']) ?></span><small class="d-block text-secondary"><?= e($j['completed_at']??$j['scheduled_date']??'') ?></small></div><?php endforeach; ?></div></div><div class="card p-4"><h2 class="h5">Warranty</h2><?php if(!$warranties): ?><p class="text-secondary mb-0">No warranty record.</p><?php endif; ?><?php foreach($warranties as $w): ?><p><strong><?= e($w['job_number']) ?></strong><br><?= e($w['warranty_start'].' – '.$w['warranty_end']) ?> · <?= e($w['status']) ?><br><small><?= e($w['coverage']??'') ?></small></p><?php endforeach; ?><hr><small><?= e($asset['tenant_name']) ?> · <?= e($asset['tenant_phone']??'') ?> · <?= e($asset['tenant_email']??'') ?></small></div></main></body></html>
